import{_ as r,a0 as l,w as d,s as c,ao as s,I as a,a1 as o,A as n,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何在  Linux/Unix 中不重启 Vim 而重新加载 .vimrc 文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在  Linux/Unix 中不重启 Vim 而重新加载 .vimrc 文件 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在  Linux/Unix 中不重启 Vim 而重新加载 .vimrc 文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在  Linux/Unix 中不重启 Vim 而重新加载 .vimrc 文件 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20180201 How to reload .vimrc file without restarting vim on Linux-Unix","title":"如何在  Linux/Unix 中不重启 Vim 而重新加载 .vimrc 文件","tag":"201802","desc":""},"relativePath":"201802/20180201 How to reload .vimrc file without restarting vim on Linux-Unix.md","filePath":"[post].md"}'),p={name:"201802/20180201 How to reload .vimrc file without restarting vim on Linux-Unix.md"};function m(u,i,v,f,g,x){const t=l("Link");return d(),c("div",null,[i[17]||(i[17]=s(`<h1 id="如何在-linux-unix-中不重启-vim-而重新加载-vimrc-文件" tabindex="-1">如何在 Linux/Unix 中不重启 Vim 而重新加载 .vimrc 文件 <a class="header-anchor" href="#如何在-linux-unix-中不重启-vim-而重新加载-vimrc-文件" aria-label="Permalink to “如何在  Linux/Unix 中不重启 Vim 而重新加载 .vimrc 文件”">​</a></h1><p>我是一位新的 Vim 编辑器用户。我通常使用 <code>:vs ~/.vimrc</code> 来加载 <code>~/.vimrc</code> 配置。而当我编辑 <code>.vimrc</code> 时，我需要不重启 Vim 会话而重新加载它。在 Linux 或者类 Unix 系统中，如何在编辑 <code>.vimrc</code> 后，重新加载它而不用重启 Vim 呢？</p><p>Vim 是自由开源并且向上兼容 Vi 的编辑器。它可以用来编辑各种文本。它在编辑用 C/Perl/Python 编写的程序时特别有用。可以用它来编辑 Linux/Unix 配置文件。<code>~/.vimrc</code> 是你个人的 Vim 初始化和自定义文件。</p><h3 id="如何在不重启-vim-会话的情况下重新加载-vimrc" tabindex="-1">如何在不重启 Vim 会话的情况下重新加载 .vimrc <a class="header-anchor" href="#如何在不重启-vim-会话的情况下重新加载-vimrc" aria-label="Permalink to “如何在不重启 Vim 会话的情况下重新加载 .vimrc”">​</a></h3><p>在 Vim 中重新加载 <code>.vimrc</code> 而不重新启动的流程：</p><ol><li>输入 <code>vim filename</code> 启动 vim</li><li>按下 <code>Esc</code> 接着输入 <code>:vs ~/.vimrc</code> 来加载 vim 配置</li><li>像这样添加自定义配置：</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>filetype indent plugin on</span></span>
<span class="line"><span>set number</span></span>
<span class="line"><span>syntax on</span></span></code></pre></div><ol start="4"><li>使用 <code>:wq</code> 保存文件，并从 <code>~/.vimrc</code> 窗口退出</li><li>输入下面任一命令重载 <code>~/.vimrc</code>：<code>:so $MYVIMRC</code> 或者 <code>:source ~/.vimrc</code>。</li></ol>`,8)),a("p",null,[o(t,{href:"https://www.cyberciti.biz/media/new/faq/2018/02/How-to-reload-.vimrc-file-without-restarting-vim.jpg"},{default:n(()=>[...i[0]||(i[0]=[a("img",{src:"https://www.cyberciti.biz/media/new/faq/2018/02/How-to-reload-.vimrc-file-without-restarting-vim.jpg",alt:"How to reload .vimrc file without restarting vim"},null,-1)])]),_:1})]),i[18]||(i[18]=s(`<p><em>图1：编辑 ~/.vimrc 并在需要时重载它而不用退出 vim，这样你就可以继续编辑程序了</em></p><p><code>:so[urce]! {file}</code> 这个 vim 命令会从给定的文件比如 <code>~/.vimrc</code> 读取配置。就像你输入的一样，这些命令是在普通模式下执行的。当你在 <code>:global</code>、:<code>argdo</code>、 <code>:windo</code>、<code>:bufdo</code> 之后、循环中或者跟着另一个命令时，显示不会再在执行命令时更新。</p><h3 id="如何设置按键来编辑并重载-vimrc" tabindex="-1">如何设置按键来编辑并重载 ~/.vimrc <a class="header-anchor" href="#如何设置按键来编辑并重载-vimrc" aria-label="Permalink to “如何设置按键来编辑并重载 ~/.vimrc”">​</a></h3><p>在你的 <code>~/.vimrc</code> 后面跟上这些：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot; Edit vimr configuration file</span></span>
<span class="line"><span>nnoremap confe :e $MYVIMRC&lt;CR&gt;</span></span>
<span class="line"><span>&quot; Reload vims configuration file</span></span>
<span class="line"><span>nnoremap confr :source $MYVIMRC&lt;CR&gt;</span></span></code></pre></div><p>现在只要按下 <code>Esc</code> 接着输入 <code>confe</code> 就可以编辑 <code>~/.vimrc</code>。按下 <code>Esc</code> ，接着输入 <code>confr</code> 以重新加载。一些人喜欢在 <code>.vimrc</code> 中使用 <code>&lt;Leader&gt;</code> 键。因此上面的映射变成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot; Edit vimr configuration file</span></span>
<span class="line"><span>nnoremap &lt;Leader&gt;ve :e $MYVIMRC&lt;CR&gt;</span></span>
<span class="line"><span>&quot; Reload vimr configuration file</span></span>
<span class="line"><span>nnoremap &lt;Leader&gt;vr :source $MYVIMRC&lt;CR&gt;</span></span></code></pre></div><p><code>&lt;Leader&gt;</code> 键默认映射成 <code>\\</code> 键。因此只要输入 <code>\\</code> 接着 <code>ve</code> 就能编辑文件。按下 <code>\\</code> 接着 <code>vr</code> 就能重载 <code>~/vimrc</code>。</p><p>这就完成了，你可以不用再重启 Vim 就能重新加载 <code>.vimrc</code> 了。</p><h3 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to “关于作者”">​</a></h3>`,10)),a("p",null,[i[2]||(i[2]=e("作者是 nixCraft 的创建者，经验丰富的系统管理员，也是 Linux / Unix shell 脚本的培训师。他曾与全球客户以及IT、教育、国防和太空研究以及非营利部门等多个行业合作。在 [Twitter][9]、[Facebook][10]、[Google +][11] 上关注他。通过",-1)),o(t,{href:"https://www.cyberciti.biz/atom/atom.xml"},{default:n(()=>[...i[1]||(i[1]=[e("RSS/XML 订阅",-1)])]),_:1}),i[3]||(i[3]=e("获取最新的系统管理、Linux/Unix 以及开源主题教程。",-1))]),i[19]||(i[19]=a("hr",null,null,-1)),a("p",null,[i[5]||(i[5]=e("via: ",-1)),o(t,{href:"https://www.cyberciti.biz/faq/how-to-reload-vimrc-file-without-restarting-vim-on-linux-unix/"},{default:n(()=>[...i[4]||(i[4]=[e("https://www.cyberciti.biz/faq/how-to-reload-vimrc-file-without-restarting-vim-on-linux-unix/",-1)])]),_:1})]),a("p",null,[i[9]||(i[9]=e("作者：",-1)),o(t,{href:"https://www.cyberciti.biz/"},{default:n(()=>[...i[6]||(i[6]=[e("Vivek Gite",-1)])]),_:1}),i[10]||(i[10]=e(" 译者：",-1)),o(t,{href:"https://github.com/geekpi"},{default:n(()=>[...i[7]||(i[7]=[e("geekpi",-1)])]),_:1}),i[11]||(i[11]=e(" 校对：",-1)),o(t,{href:"https://github.com/wxy"},{default:n(()=>[...i[8]||(i[8]=[e("wxy",-1)])]),_:1})]),a("p",null,[i[14]||(i[14]=e("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...i[12]||(i[12]=[e("LCTT",-1)])]),_:1}),i[15]||(i[15]=e(" 原创编译，",-1)),o(t,{href:"https://linux.cn/"},{default:n(()=>[...i[13]||(i[13]=[e("Linux中国",-1)])]),_:1}),i[16]||(i[16]=e(" 荣誉推出",-1))])])}const k=r(p,[["render",m]]);export{w as __pageData,k as default};
